import{_ as n,c as t,o as a,ag as s}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Channels and Connectors","description":"The fundamental building blocks","frontmatter":{"title":"Channels and Connectors","description":"The fundamental building blocks"},"headers":[],"relativePath":"engine/channels_and_connectors.md","filePath":"engine/channels_and_connectors.md","lastUpdated":1788476353000}'),o={name:"engine/channels_and_connectors.md"};function r(i,e,c,d,l,h){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="channels-and-connectors" tabindex="-1">Channels and Connectors <a class="header-anchor" href="#channels-and-connectors" aria-label="Permalink to &quot;Channels and Connectors&quot;">​</a></h1><p>Channels are the primary building blocks in OIE. A channel represents a complete integration workflow. It defines where data comes from, how it gets transformed, and where it ultimately goes.</p><h2 id="about-channels-and-connectors" tabindex="-1">About channels and connectors <a class="header-anchor" href="#about-channels-and-connectors" aria-label="Permalink to &quot;About channels and connectors&quot;">​</a></h2><p>A channel is made up of <strong>connectors</strong>. There are two kinds: a <strong>source connector</strong> brings data into OIE, while a <strong>destination connector</strong> pushes data out to an external system. Every channel has one source connector and one or more destinations. This means a single channel can take data from one place and deliver it to several different targets. For instance, receiving an HL7 message over TCP and simultaneously writing it to a file and inserting selected fields into a database.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        Channel                           │</span></span>
<span class="line"><span>│                                                          │</span></span>
<span class="line"><span>│  ┌────────────┐    ┌──────────────┐    ┌──────────────┐  │</span></span>
<span class="line"><span>│  │   Source    │───&gt;│   Filters    │───&gt;│ Destination  │  │</span></span>
<span class="line"><span>│  │ Connector   │    │ Transformers │    │ Connector(s) │  │</span></span>
<span class="line"><span>│  └────────────┘    └──────────────┘    └──────────────┘  │</span></span>
<span class="line"><span>│                                                          │</span></span>
<span class="line"><span>│  Scripts: Deploy | Preprocessor | Post Processor | Undeploy│</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="general-channel-properties" tabindex="-1">General channel properties <a class="header-anchor" href="#general-channel-properties" aria-label="Permalink to &quot;General channel properties&quot;">​</a></h2><p>These are configured on the Summary tab of the channel editor and cover the overall behavior of the channel:</p><ul><li><strong>Unique ID, name, and description</strong></li><li><strong>Code Template Libraries</strong>. Controls which reusable JavaScript functions are accessible within the channel</li><li><strong>Library Resources</strong>. Specifies which custom Java classes can be referenced by the channel&#39;s connectors or scripts</li><li><strong>Deploy/Start Dependencies</strong>. Lets you define ordering relationships between channels so certain channels come online before others</li><li><strong>Attachment Handler</strong>. Provides a way to extract pieces of incoming messages and store them separately. As a message moves through the channel, multiple copies of its content are held in memory at the same time (raw, transformed, and encoded versions). Attachment data is stored only once rather than being duplicated in each copy, which can significantly reduce memory usage</li><li><strong>Message Storage Settings</strong>. Governs what message data gets persisted, whether encryption is applied, and whether connectors can use persistent queuing</li><li><strong>Message Pruning Settings</strong>. Defines retention periods for message data and offers the option to archive messages to disk before they are removed</li><li><strong>Custom Metadata Columns</strong>. Lets you pull specific values out of messages and store them as searchable columns in the Message Browser</li><li><strong>Channel Tags</strong>. Labels for organizing channels into logical groups</li></ul><h2 id="source-connector" tabindex="-1">Source connector <a class="header-anchor" href="#source-connector" aria-label="Permalink to &quot;Source connector&quot;">​</a></h2><p>Each channel has exactly one source connector responsible for bringing data into OIE. Beyond the standard filter and transformer components, source connectors offer several additional features:</p><ul><li><strong>Source Queue</strong>. When turned on, the channel operates in store-and-forward mode: it accepts the incoming data and immediately sends back an acknowledgement without waiting for the full processing pipeline to finish.</li><li><strong>Batch Processor</strong>. When activated, a single inbound payload gets broken apart into individual messages, each of which travels through the channel independently.</li><li><strong>Response Selector</strong>. Configures what gets sent back to the system that delivered the message. Options include auto-generating a response based on the source data type, forwarding the reply from a particular destination, or providing an entirely custom response.</li><li><strong>Max Processing Threads</strong>. Defaults to 1, meaning messages go through the channel one at a time. Raising this value increases throughput but sacrifices guaranteed message ordering. This setting does not affect asynchronous processes such as destination queuing.</li></ul><h2 id="destination-connectors" tabindex="-1">Destination connectors <a class="header-anchor" href="#destination-connectors" aria-label="Permalink to &quot;Destination connectors&quot;">​</a></h2><p>A channel needs at least one destination connector to deliver data outward. Destinations also have some features beyond the standard filter and transformer:</p><ul><li><strong>Enabled</strong>. A toggle that controls whether the destination participates in processing. At least one destination must remain enabled at all times.</li><li><strong>Wait for previous destination</strong>. Determines which <strong>chain</strong> the destination belongs to (see <a href="#destination-chains">Destination Chains</a> below).</li><li><strong>Response Transformer</strong>. A secondary transformer that operates on the reply received from the external system rather than the outbound message itself. It has its own pair of data types (response inbound and response outbound). A destination response includes the response data, the <strong>status</strong> (e.g. SENT, ERROR), a <strong>status message</strong>, and an <strong>error message</strong>. The response transformer can modify all of these. For example, overriding an ERROR status to SENT based on custom logic, or forcing a message into the queue. Note that response transformers only execute when there is an actual response payload to transform (e.g. they will not run if a connection to the remote server fails entirely). The exception is when the response inbound data type is set to Raw, in which case the response transformer always executes regardless of whether a response payload exists.</li></ul><h2 id="channel-scripts" tabindex="-1">Channel scripts <a class="header-anchor" href="#channel-scripts" aria-label="Permalink to &quot;Channel scripts&quot;">​</a></h2><p>Each channel has four configurable scripts that run at specific points in the lifecycle:</p><table tabindex="0"><thead><tr><th>Script</th><th>When It Runs</th></tr></thead><tbody><tr><td><strong>Deploy Script</strong></td><td>Executes once immediately before the channel is deployed</td></tr><tr><td><strong>Preprocessor Script</strong></td><td>Fires for each message, after the source connector receives it and after any attachment extraction, but before filtering and transformation begin. Used to modify the raw message.</td></tr><tr><td><strong>Post Processor Script</strong></td><td>Fires for each message after the source and all destinations have finished (not counting asynchronous queue processing), but before the source connector sends its response. Has access to destination responses and can return a custom reply for the source to use.</td></tr><tr><td><strong>Undeploy Script</strong></td><td>Executes once after the channel is undeployed</td></tr></tbody></table><h2 id="connector-components" tabindex="-1">Connector components <a class="header-anchor" href="#connector-components" aria-label="Permalink to &quot;Connector components&quot;">​</a></h2><p>Every connector, whether source or destination, shares a common set of building blocks:</p><h3 id="general-connector-properties" tabindex="-1">General connector properties <a class="header-anchor" href="#general-connector-properties" aria-label="Permalink to &quot;General connector properties&quot;">​</a></h3><p>Each connector is identified by a name and a <strong>metadata ID</strong>. The source connector is always named &quot;Source&quot; with a metadata ID of 0. Destination connectors have user-defined names and metadata IDs that start at 1 and increment from there. Renaming a destination does not change its metadata ID.</p><h3 id="connector-specific-properties" tabindex="-1">Connector-specific properties <a class="header-anchor" href="#connector-specific-properties" aria-label="Permalink to &quot;Connector-specific properties&quot;">​</a></h3><p>The configuration fields vary by connector type. A TCP Listener has completely different settings from a Database Writer, for instance. See the <a href="./connector_reference.html">Connector Reference</a> for specifics.</p><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><p>Evaluates incoming messages and decides whether they should continue through the pipeline. See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="transformer" tabindex="-1">Transformer <a class="header-anchor" href="#transformer" aria-label="Permalink to &quot;Transformer&quot;">​</a></h3><p>Modifies messages, converts between formats, and extracts values for use in templates and downstream steps. Every transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong> that control how data is parsed and converted. See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h2 id="destination-chains" tabindex="-1">Destination chains <a class="header-anchor" href="#destination-chains" aria-label="Permalink to &quot;Destination chains&quot;">​</a></h2><p>Destinations within a channel are organized into <strong>chains</strong>. Chains run in parallel with each other, but within a single chain, destinations are processed sequentially. A destination whose <strong>Wait for previous destination</strong> setting is unchecked marks the beginning of a new chain. The first destination in a channel always starts the first chain.</p><p>For example, with 5 destinations where Destination 3 does not wait on Destination 2 (starting a new chain):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Connector</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>   Preprocessor</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>  ┌────┴────┐</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Chain 1   Chain 2</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Dest 1    Dest 3</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Dest 2    Dest 4</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>          Dest 5</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>  └────┬────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>  Postprocessor</span></span></code></pre></div><p>Here, Chain 1 (Dest 1 and 2) and Chain 2 (Dest 3, 4, and 5) run concurrently. If each destination takes 1 second, total processing time is 3 seconds (the longer chain) rather than 5.</p><h2 id="channel-groups" tabindex="-1">Channel groups <a class="header-anchor" href="#channel-groups" aria-label="Permalink to &quot;Channel groups&quot;">​</a></h2><p>Channels can be sorted into <strong>groups</strong> for organizational purposes. Groups have no effect on processing behavior.</p><ul><li>Create groups in the Channels panel</li><li>Drag and drop channels between groups</li><li>Deploy/undeploy entire groups at once</li></ul><h2 id="channel-states" tabindex="-1">Channel states <a class="header-anchor" href="#channel-states" aria-label="Permalink to &quot;Channel states&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><strong>Started</strong></td><td>Channel is actively processing messages</td></tr><tr><td><strong>Stopped</strong></td><td>Channel is deployed but not processing</td></tr><tr><td><strong>Paused</strong></td><td>Channel is deployed, source is paused (queued messages still process)</td></tr><tr><td><strong>Undeployed</strong></td><td>Channel exists but is not loaded into the engine</td></tr></tbody></table><h2 id="connector-types" tabindex="-1">Connector types <a class="header-anchor" href="#connector-types" aria-label="Permalink to &quot;Connector types&quot;">​</a></h2><p>See <a href="./connector_reference.html">Connector Reference</a> for detailed documentation on each connector type.</p><h3 id="source-connectors" tabindex="-1">Source connectors <a class="header-anchor" href="#source-connectors" aria-label="Permalink to &quot;Source connectors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Connector</th><th>Protocol/Method</th></tr></thead><tbody><tr><td>Channel Reader</td><td>Internal channel-to-channel</td></tr><tr><td>DICOM Listener</td><td>DICOM protocol</td></tr><tr><td>Database Reader</td><td>JDBC polling</td></tr><tr><td>File Reader</td><td>File/FTP/SFTP/S3/SMB/WebDAV</td></tr><tr><td>HTTP Listener</td><td>HTTP/HTTPS</td></tr><tr><td>JMS Listener</td><td>Java Message Service</td></tr><tr><td>JavaScript Reader</td><td>Custom scripted source</td></tr><tr><td>TCP Listener</td><td>TCP/MLLP</td></tr><tr><td>Web Service Listener</td><td>SOAP/WSDL</td></tr></tbody></table><h3 id="destination-connectors-1" tabindex="-1">Destination connectors <a class="header-anchor" href="#destination-connectors-1" aria-label="Permalink to &quot;Destination connectors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Connector</th><th>Protocol/Method</th></tr></thead><tbody><tr><td>Channel Writer</td><td>Internal channel-to-channel</td></tr><tr><td>DICOM Sender</td><td>DICOM protocol</td></tr><tr><td>Database Writer</td><td>JDBC insert/update</td></tr><tr><td>Document Writer</td><td>PDF/RTF document generation</td></tr><tr><td>File Writer</td><td>File/FTP/SFTP/S3/SMB/WebDAV</td></tr><tr><td>HTTP Sender</td><td>HTTP/HTTPS</td></tr><tr><td>JMS Sender</td><td>Java Message Service</td></tr><tr><td>JavaScript Writer</td><td>Custom scripted destination</td></tr><tr><td>SMTP Sender</td><td>Email</td></tr><tr><td>TCP Sender</td><td>TCP/MLLP</td></tr><tr><td>Web Service Sender</td><td>SOAP/WSDL</td></tr></tbody></table><p>Additional connectors are available as community extensions. See the <a href="./extension_catalog.html">Extension Catalog</a>.</p>`,44)]))}const g=n(o,[["render",r]]);export{u as __pageData,g as default};
